class Solution {
  public List<Integer> solveQueries(int[] nums, int[] queries) {
    int n = nums.length;
    Map<Integer, List<Integer>> positions = new HashMap<>();
    for (int i = 0; i < n; i++) positions.computeIfAbsent(nums[i], v -> new ArrayList<>()).add(i);
    int[] nearest = new int[n];
    Arrays.fill(nearest, -1);
    for (List<Integer> p : positions.values()) {
      int s = p.size();
      if (s < 2) continue;
      for (int t = 0; t < s; t++) {
        int i = p.get(t);
        nearest[i] =
            Math.min(circular(i, p.get((t + 1) % s), n), circular(i, p.get((t - 1 + s) % s), n));
      }
    }
    List<Integer> ans = new ArrayList<>();
    for (int q : queries) ans.add(nearest[q]);
    return ans;
  }

  private int circular(int a, int b, int n) {
    int d = Math.abs(a - b);
    return Math.min(d, n - d);
  }
}
